import numpy as np, json
V = 8
xi = np.exp(1j*2*np.pi*np.arange(V)/V)
def step(z, x, eta):
    nu = (xi[x]-z)/(1-np.conj(z)*xi[x])
    u = eta*nu
    return (u+z)/(1+np.conj(z)*u)
def center(a, b, q):
    for s in (np.exp(1j*np.pi/3), np.exp(-1j*np.pi/3)):
        cand = (s*a*(q-b)-b*(q-a))/(s*(q-b)-(q-a))
        if abs(cand) < 1:
            return cand
def readout(z):
    P = (1-abs(z)**2)/np.abs(z-xi)**2
    return P/P.sum()
z = 0j; c = 0; B = []
for x in [0, 2, 1]:
    if c == 2 and len(set(B+[x])) == 3:
        z = center(xi[B[0]], xi[B[1]], xi[x])
    else:
        eta = 1.0/(c+2) if c <= 2 else 1.0/(c+1)
        z = step(z, x, eta)
    if c < 2:
        B.append(x)
    c += 1
    if c == 2:
        z2 = z; p2 = readout(z)
p3 = readout(z)
print(json.dumps({"z_after_2": [round(float(z2.real),4), round(float(z2.imag),4)], "p_after_2": [round(float(v),3) for v in p2], "argmax_after_2": int(np.argmax(p2)), "z_after_3": [round(float(z.real),4), round(float(z.imag),4)], "p_after_3": [round(float(v),3) for v in p3], "mass_0_2_after_3": round(float(p3[:3].sum()),3)}))
